最Python风格的单例实现:

# 方式1: 模块本身就是单例
# config.py
settings = {'key': 'value'}

# 方式2: 用装饰器
def singleton(cls):
    instances = {}
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return get_instance
